describe("Cart — pricing pipeline", () => {
  it("computes correct subtotal", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(450),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
    // tax is computed on discounted subtotal
    expect(tax.computeTaxCents).toHaveBeenCalledWith(9000, "US-CA");
    expect(totals.taxCents).toBe(450);
    // shipping receives discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      9000,
    );
    expect(totals.shippingCents).toBe(599);
    expect(totals.totalCents).toBe(9000 + 450 + 599);
  });

  it("clamps discount into [0, subtotal]", () => {
    // discount exceeds subtotal
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0); // no tax, no shipping by default
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart.checkout()", () => {
  describe("no collaborators", () => {
    it("returns totals and snapshot without collaborators", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("price refresh", () => {
    it("refreshes prices via PriceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates PriceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "fetch failed",
      );
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("inventory checking", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "out of stock" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(2);
        expect(ie.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial via availableQuantity", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(3);
      }
    });

    it("checks first product denial wins with multiple lines", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
