toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any positive amount", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero amount", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative amount", () => {
    expect(calc.computeTaxCents(-500, "FR")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects a negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects a default rate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects an invalid rate in the rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("rejects a negative rate in the rates map", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
    });

    it("accepts valid rates and default", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "US-OR": 0, DE: 0.19 },
      0.1,
    );

    it("uses the region-specific rate when available", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("uses the default rate for an unknown region", () => {
      // 10% of 5000 = 500
      expect(calc.computeTaxCents(5000, "GB")).toBe(500);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-100, "DE")).toBe(0);
    });

    it("rounds down to the nearest cent", () => {
      // 19% of 101 = 19.19 → 19
      expect(calc.computeTaxCents(101, "DE")).toBe(19);
    });

    it("returns 0 for a region with 0 rate", () => {
      expect(calc.computeTaxCents(10000, "US-OR")).toBe(0);
    });

    it("uses default rate of 0 when not specified", () => {
      const calc2 = new RegionalTaxCalculator({});
      expect(calc2.computeTaxCents(5000, "US")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("fetches rate from provider and computes tax", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US-CA")).toBe(875);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.19),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 19% of 101 = 19.19 → 19
    expect(await calc.computeTaxCents(101, "DE")).toBe(19);
  });

  it("throws RangeError when provider returns out-of-range rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("service down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service down",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for an empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 500 }, quantity: 1 },
    ];
    // (200*2) + (500*1) = 900
    expect(totalLineWeightGrams(lines)).toBe(900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

