toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  price: number,
  qty: number,
  weight?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: price, weightGrams: weight },
  quantity: qty,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty lines", () => {
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 1000, 1)], 1000)).toBe(
        599,
      );
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 4999, 1)], 4999)).toBe(
        599,
      );
    });

    it("returns flat fee when freeOverCents is not set", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([makeLine("a", 100000, 1)], 100000),
      ).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // product has no weight
      expect(
        calc.computeShippingCents([makeLine("a", 1000, 1)], 1000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g → first bracket (≤500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 200)], 100),
      ).toBe(300);
    });

    it("uses the bracket boundary exactly", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → first bracket
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 500)], 100),
      ).toBe(300);
      // 501g → second bracket
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 501)], 100),
      ).toBe(500);
    });

    it("multiplies weight by quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 3 items × 200g = 600g → second bracket (≤1000g) → 500
      expect(
        calc.computeShippingCents([makeLine("a", 100, 3, 200)], 300),
      ).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000g → overflow → 2000
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 6000)], 100),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g → last bracket cost → 1000
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 6000)], 100),
      ).toBe(1000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1000 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      // 200g → first bracket (≤500g) → 300
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1, 200)], 100),
      ).toBe(300);
    });
  });
});

