import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (
  id: string,
  price: number,
  weight?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart — line management", () => {
  it("starts empty", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0]!.quantity).toBe(2);
  });

  it("merges quantities when adding the same product twice", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("rejects non-positive quantity in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents in add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the item", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clear removes all items", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    cart.add(product("b", 2000), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(1); // unchanged
  });
});

describe("Cart — pricing pipeline", () => {
  it("computes correct subtotal", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(450),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 5000), 2); // subtotal = 10000

    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000);
    // tax is computed on discounted subtotal
    expect(tax.computeTaxCents).toHaveBeenCalledWith(9000, "US-CA");
    expect(totals.taxCents).toBe(450);
    // shipping receives discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      9000,
    );
    expect(totals.shippingCents).toBe(599);
    expect(totals.totalCents).toBe(9000 + 450 + 599);
  });

  it("clamps discount into [0, subtotal]", () => {
    // discount exceeds subtotal
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(99999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0); // no tax, no shipping by default
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

