import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart.checkout()", () => {
  describe("no collaborators", () => {
    it("returns totals and snapshot without collaborators", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });
  });

  describe("price refresh", () => {
    it("refreshes prices via PriceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates PriceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "fetch failed",
      );
    });

    it("throws RangeError when fetcher returns invalid price", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        RangeError,
      );
    });
  });

  describe("inventory checking", () => {
    it("succeeds when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: false, reason: "out of stock" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(2);
        expect(ie.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial via availableQuantity", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(3);
      }
    });

    it("checks first product denial wins with multiple lines", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);

      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({
            available: false,
            reason: "b is out",
          }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).productId).toBe("b");
      }
    });

    it("uses default reason message when reason is not provided", async () => {
      const cart = new Cart();
      cart.add(product("x", 500), 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.message).toContain("x");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses async tax provider for tax computation", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        region: "US-CA",
      });
      cart.add(product("a", 10000), 1); // subtotal 10000, discount 1000, taxable 9000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      expect(result.totals.taxCents).toBe(900); // 10% of 9000
      expect(result.totals.discountCents).toBe(1000);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline integration", () => {
    it("refreshes prices, checks inventory, and computes async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "DE",
      });
      cart.add(product("a", 1000), 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.19),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed subtotal = 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount = 20% of 2400 = 480
      expect(result.totals.discountCents).toBe(480);
      // taxable = 2400 - 480 = 1920, tax = floor(1920 * 0.19) = floor(364.8) = 364
      expect(result.totals.taxCents).toBe(364);
      // total = 1920 + 364 + 0 = 2284
      expect(result.totals.totalCents).toBe(2284);
    });
  });
});

describe("InventoryError", () => {
  it("has correct shape and properties", () => {
    const err = new InventoryError("no stock", "prod-1", 5, 2);
    expect(err).toBeInstanceOf(Error);
    expect(err).toBeInstanceOf(InventoryError);
    expect(err.name).toBe("InventoryError");
    expect(err.message).toBe("no stock");
    expect(err.productId).toBe("prod-1");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
  });

  it("handles undefined available", () => {
    const err = new InventoryError("gone", "prod-2", 3, undefined);
    expect(err.available).toBeUndefined();
  });
});

describe("refreshPrices", () => {
  // Tested indirectly via checkout, but also directly for edge cases
  it("throws RangeError for non-integer price", async () => {
    const { refreshPrices } = await import("../src/inventory.ts");
    const lines = [
      {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("returns updated lines with new prices", async () => {
    const { refreshPrices } = await import("../src/inventory.ts");
    const lines = [
      {
        product: { id: "a", name: "A", unitPriceCents: 100 },
        quantity: 2,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.unitPriceCents).toBe(200);
    expect(result[0]!.quantity).toBe(2);
  });
});

